def square(x: int) -> int:
    """Return the square of an integer."""
    return x * x


def squares(xs: list[int]) -> list[int]:
    """Square every element of xs in parallel using a thread pool."""
    from concurrent.futures import ThreadPoolExecutor

    with ThreadPoolExecutor() as executor:
        return list(executor.map(square, xs))


def test_square() -> None:
    assert square(0) == 0
    assert square(3) == 9
    assert square(-4) == 16


def test_squares_empty() -> None:
    assert squares([]) == []


def test_squares_single() -> None:
    assert squares([5]) == [25]


def test_squares_order() -> None:
    assert squares([1, -2, 3, 0, 4]) == [1, 4, 9, 0, 16]


def test_squares_many() -> None:
    assert squares(list(range(20))) == [x * x for x in range(20)]

